  function exerciseExplorer(groups,selected){const term=norm(P.exerciseQuery),list=groups.filter(g=>!term||norm(g.label).includes(term));if(!selected&&list.length)selected=list[0];const sets=selected?(state.sets||[]).filter(s=>selected.rows.some(r=>r.source_record_id===s.exercise_source_record_id)):[];return `<input id="productExerciseSearch" type="search" value="${escapeAttr(P.exerciseQuery)}" placeholder="Buscar exercício" style="width:100%;border:1px solid var(--p-line);border-radius:11px;padding:9px;margin-bottom:9px"><div class="productExercisePicker"><div class="productExerciseList">${list.slice(0,80).map(g=>`<button data-ex-key="${escapeAttr(g.key)}" class="${selected?.key===g.key?'active':''}"><b>${esc(g.label)}</b><small>${unique(g.rows.map(x=>day(x.workout_date))).length} sessão(ões)</small></button>`).join('')||empty('Nenhum exercício encontrado.')}</div><div class="productExerciseDetail">${selected?exerciseDetail(selected,sets):empty('Selecione um exercício.')}</div></div>`}
  function exerciseDetail(group,sets){const dates=unique(group.rows.map(x=>day(x.workout_date))).sort(),byUnit={};for(const s of sets){const v=num(s.weight??s.load??s.weight_value);if(v==null)continue;const u=String(s.weight_unit||s.unit||'unidade não informada'),d=day(s.workout_date);if(!byUnit[u])byUnit[u]={};byUnit[u][d]=Math.max(byUnit[u][d]??-Infinity,v)}const blocks=Object.entries(byUnit).map(([u,map])=>{const pts=Object.entries(map).sort((a,b)=>a[0].localeCompare(b[0])),max=Math.max(1,...pts.map(x=>x[1]));return `<div class="productSection"><b style="font-size:10px">Maior carga por sessão · ${esc(u)}</b><div class="productTinyBars">${pts.slice(-16).map(([d,v])=>`<div class="productTinyBar"><em>${fmtNum(v,1)}</em><i style="height:${Math.max(4,v/max*85)}%"></i><span>${d.slice(5).replace('-','/')}</span></div>`).join('')}</div></div>`}).join('');return `<div class="productCardHead"><div><h3>${esc(group.label)}</h3><p>${dates.length} sessão(ões) · ${sets.length} série(s) estruturada(s) · ${dates.length?`${fmtDate(dates[0])} → ${fmtDate(dates.at(-1))}`:''}</p></div></div>${blocks||empty('Sem carga numérica comparável por unidade.')}`}

