  function monthBuckets(rows,count=12){const m=new Map();for(const r of rows){const d=day(r.nutrition_date);if(!d)continue;const k=d.slice(0,7),g=m.get(k)||{key:k,days:new Set(),rows:[]};g.days.add(d);g.rows.push(r);m.set(k,g)}return [...m.values()].sort((a,b)=>a.key.localeCompare(b.key)).slice(-count)}
