  function appleCap(apple,type,label){const ds=unique(apple.filter(x=>x.metric_type===type).map(x=>day(x.measured_at)));return `<div class="productCoverage"><span>${esc(label)}</span><strong>${ds.length}</strong><small>dia(s) normalizado(s)</small></div>`}
